import { z } from 'zod';
import { UserSkillId } from './skill-identity';

const NodeId = z.string().regex(/^[A-Za-z][A-Za-z0-9_]{0,63}$/);
/** Installer-generated subset of the official pcg architecture format. */
export const SkillWorkflow = z.object({
  schema: z.literal('pcg.architecture.v1'),
  entry: UserSkillId,
  kind: z.literal('agent_workflow'),
  layout: z.enum(['linear', 'tree']),
  tasks: z.array(z.object({
    id: NodeId,
    parent: NodeId.nullable(),
    role: z.enum(['agent', 'subagent', 'local']),
    label: z.string().min(1).max(160),
    function: z.string().min(1).max(2000),
    entry: UserSkillId.nullable(),
    optional: z.boolean(),
    outputs: z.array(z.object({
      id: NodeId, label: z.string().min(1).max(160),
      kind: z.enum(['file', 'model', 'image', 'link']),
      retain: z.enum(['keep', 'cache']),
      semantics: z.array(z.enum(['deliverable', 'derived', 'cache'])).max(3),
    }).strict()).max(20),
  }).strict()).min(2).max(80),
}).strict();
export type SkillWorkflow = z.infer<typeof SkillWorkflow>;
